from __future__ import annotations

import time

from . import native
from .errors import PipeBusyError, WPipeError
from .framing import FrameReader, encode_frame, write_all
from .native import PIPE_PREFIX

__all__ = ["PipeClient"]

# 单次 ``WaitNamedPipe`` 的最长等待片（毫秒）：把长预算切成小片，便于按
# deadline 精确收尾，也避免 ``timeout_ms`` 异常大时的整数溢出。
_WAIT_SLICE_MS = 1000


def _resolve_name(name):
    """把 ``foo`` 形态补全为 ``\\\\.\\pipe\\foo``。"""
    if isinstance(name, str) and name.lower().startswith(PIPE_PREFIX.lower()):
        return PIPE_PREFIX + name[len(PIPE_PREFIX):]
    return PIPE_PREFIX + str(name)


