    """命名管道客户端。

    参数
    ----
    name        管道名（``foo`` 或 ``\\\\.\\pipe\\foo`` 形式）。
    timeout_ms  连接等待预算（毫秒）：目标实例全部被占用时，在这个预算内
                用 ``WaitNamedPipe`` 等待并重试。
    buffer_size 每次底层读写的缓冲区大小。
    """

    def __init__(self, name, timeout_ms=5000, buffer_size=4096):
        self.name = name
        self.timeout_ms = timeout_ms
        self.buffer_size = buffer_size
        self._handle = None
        self._resolved = None
        # 分帧读的重组缓冲：跨底层读的半包留在这里，粘在一起的多帧在这里被拆开。
        self._frames = FrameReader(self._read_chunk, chunk_size=buffer_size)

    # ------------------------------------------------------------ 内部读写
    def _read_chunk(self, size):
        return native.read(self._handle, size)

    def _write_chunk(self, data):
        return native.write(self._handle, data)

    @property
    def resolved_name(self):
        """规范化后的管道名（``connect()`` 成功后可用）。"""
        return self._resolved

    # ------------------------------------------------------------ 生命周期
    def connect(self):
        """连接到服务端管道，成功返回 ``True``。

        - 打开成功即返回；
        - 失败原因是 ``ERROR_PIPE_BUSY (231)``（实例被占满）时，在 ``timeout_ms``
          预算内用 ``WaitNamedPipe`` 等待实例释放并重试；预算耗尽抛
          ``PipeBusyError``（``kind == "busy"``）；
        - 其它失败抛 ``WPipeError(kind="connection")``。
        """
        resolved = _resolve_name(self.name)
        deadline = time.monotonic() + _budget_seconds(self.timeout_ms)
        busy_winerror = None

        while True:
            handle = native.open_pipe(resolved)
            if native.is_valid(handle):
                self._handle = handle
                self._resolved = resolved
                self._frames.reset()
                return True

            err = native.last_error()
            if err != native.ERROR_PIPE_BUSY:
                raise WPipeError("connection", "cannot open %r" % (self.name,), winerror=err)

            # 实例被占满：按预算等待实例释放，而不是立刻放弃。
            busy_winerror = err
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise PipeBusyError(self.name, timeout_ms=self.timeout_ms,
                                    winerror=busy_winerror)

            wait_ms = int(min(remaining * 1000.0, float(_WAIT_SLICE_MS)))
            if wait_ms < 1:
                wait_ms = 1
            if not native.wait_pipe(resolved, wait_ms):
                wait_err = native.last_error()
                if wait_err != native.ERROR_SEM_TIMEOUT:
                    # 例如等待期间管道消失（ERROR_FILE_NOT_FOUND）：按连接失败分类。
                    raise WPipeError("connection",
                                     "WaitNamedPipe failed for %r" % (self.name,),
                                     winerror=wait_err)

            if time.monotonic() >= deadline:
                raise PipeBusyError(self.name, timeout_ms=self.timeout_ms,
                                    winerror=busy_winerror)
            time.sleep(0.001)

    # ------------------------------------------------------------ 数据面
    def send(self, payload):
        """按「4 字节小端长度前缀 + payload」发送一条应用层消息。"""
        return write_all(self._write_chunk, encode_frame(payload))

    def recv(self):
        """接收**恰好一条**完整的应用层消息，返回其 payload（``bytes``）。

        半包会被缓冲拼装，一次底层读里粘在一起的多帧会被逐条返回；
        对端已经关闭时返回 ``None``。
        """
        return self._frames.read_frame()

    def send_bytes(self, data):
        """写入一段原始字节（不分帧）。"""
        return native.write(self._handle, data)

    def recv_raw(self):
        """读取一段原始字节（不分帧）。"""
        return native.read(self._handle, self.buffer_size)

    def close(self):
        """关闭客户端句柄（幂等）。"""
        handle, self._handle = self._handle, None
        if native.is_valid(handle):
            native.close(handle)
        self._frames.reset()


def _budget_seconds(timeout_ms):
    """把 ``timeout_ms`` 换算成秒；非法值 / 负值按 ``0``（不等待）处理。"""
    try:
        budget = float(timeout_ms)
    except (TypeError, ValueError):
        return 0.0
    if budget != budget:          # NaN
        return 0.0
    if budget < 0.0:
        return 0.0
    if budget == float("inf"):
        return float("inf")
    return budget / 1000.0
